      "interviewBlueprint": {
        "questionIntent": "신고 목록 조회의 병목을 근거로 인덱스 추가와 조인 정리를 함께 적용한 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 인턴 때 신고 목록 조회에 3.2초가 걸렸다.",
          "task": "조회 지연의 원인에 맞는 개선 방법을 선택해야 했다.",
          "action": "실행 계획에서 확인한 병목에 따라 인덱스 추가와 조인 정리를 적용했다.",
          "result": "조회 시간이 0.4초로 줄어든 결과로 개선 효과를 확인했다."
        },
        "expectedEvidence": [
          "인덱스 추가에 조인 정리까지 더한 이유를 설명한다.",
          "실행 계획에서 확인한 병목을 각 조치와 연결한다.",
          "개선 전후 조회 시간을 근거로 조치의 효과를 설명한다."
        ]
      },
      "question": "포켓마켓 인턴 때 인덱스 추가와 조인 정리로 신고 목록 조회를 3.2초에서 0.4초로 줄이셨던데요. 인덱스 추가에 조인 정리까지 더한 이유는 무엇이었나요?",
      "answerTip": "당시 실제로 판단한 내용을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획에서 드러난 병목을 짚어 인덱스 추가와 조인 정리가 각각 필요했던 이유를 설명한다.",
            "개선 전후 조회 시간을 제시하며 적용한 조치의 효과를 구체적으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "두 조치를 함께 적용한 이유는 답하지만, 확인한 병목과의 연결이나 효과 설명이 일반적이다."
          ]
        },
        "poor": {
          "criteria": [
            "조인 정리까지 적용한 이유를 설명하지 못하거나, 개선 결과만 반복한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "로그로 찾은 장애 원인을 배포 체크리스트의 재발 방지 역할과 연결하는 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 인턴 때 배포 다음 날 알림 중복 발송 문의가 들어왔다.",
          "task": "중복 발송을 복구한 뒤 같은 장애의 재발을 막아야 했다.",
          "action": "두 서버의 스케줄러 동시 실행을 찾아 잠금을 적용하고 체크리스트에 항목을 추가했다.",
          "result": "장애 원인에 연결된 배포 점검으로 같은 중복 실행을 예방하는 근거를 설명한다."
        },
        "expectedEvidence": [
          "체크리스트의 스케줄러 항목이 같은 장애를 막는 이유를 설명한다.",
          "로그에서 확인한 두 서버의 동시 실행을 점검 내용과 연결한다."
        ]
      },
      "question": "포켓마켓 인턴 때 알림 중복 발송 이후 배포 체크리스트에 스케줄러 항목을 넣으셨던데요. 그 항목으로 같은 오류의 재발을 막을 수 있다고 본 이유는 무엇이었나요?",
      "answerTip": "당시 경험을 바탕으로 생각을 구체적으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "체크리스트의 점검 내용이 두 서버의 스케줄러 동시 실행을 막는 이유를 구체적으로 설명한다.",
            "로그에서 찾은 장애 원인과 체크리스트의 재발 방지 역할을 명확히 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "체크리스트가 재발 방지에 필요한 이유는 답하지만, 실제 장애 원인과의 연결이 일반적이다."
          ]
        },
        "poor": {
          "criteria": [
            "체크리스트가 같은 오류를 막는 이유를 설명하지 못하거나, 잠금으로 수정했다는 사실만 반복한다."
          ]
        }
      }
    }
  ]
}

{
