        },
        "poor": {
          "criteria": [
            "작성한 문서나 기능만 나열하고 개발 범위에 포함한 판단 근거를 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황의 특성을 사용자가 이어서 할 행동과 화면 동작을 정하는 근거로 연결했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 예약 서비스 과제에서 예외 상황을 포함한 화면설계서 28장을 작성했다.",
          "task": "예외 상황에서도 사용자가 다음에 할 행동을 화면 흐름으로 구체화해야 했다.",
          "action": "구체적인 예외 상황의 특성에 근거해 사용자의 다음 행동과 화면 동작을 설계했다.",
          "result": "해당 예외 상황에서 이어지는 사용자 행동을 화면설계서로 설명할 수 있었다."
        },
        "expectedEvidence": [
          "예외 상황에서 사용자의 다음 행동을 정한 근거를 설명한다.",
          "그 근거가 적용된 예외 상황을 구체적으로 제시한다.",
          "판단에 따라 화면에서 이어지는 동작을 설명한다."
        ]
      },
      "question": "세탁소 예약 서비스 과제에서 예외 상황을 담은 화면설계서 28장을 작성하셨던데요. 예외 상황에서 사용자의 다음 행동을 정한 근거는 무엇이었나요?",
      "answerTip": "기억에 남는 한 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구체적인 예외 상황의 특성과 연결해 사용자의 다음 행동을 정한 근거를 설명한다.",
            "그 판단이 화면에서 어떤 동작으로 이어지는지 분명하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "사용자의 다음 행동을 정한 근거는 답하지만 예외 상황이나 화면 동작에 대한 설명이 추상적이다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 넣었다는 사실만 반복하거나 사용자의 다음 행동을 정한 근거를 설명하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "평소와 다른 처방을 발견했을 때 처방 수행보다 안전 확인을 우선해야 한다고 판단한 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 후 환자의 진통제 용량이 평소의 두 배로 처방되었다.",
          "task": "해당 처방을 확인 없이 수행해도 되는지 투약 전에 판단해야 했다.",
          "action": "용량 차이의 위험을 판단해 투약을 멈추고 담당의에게 처방을 확인했다.",
          "result": "처방 입력 오류를 확인해 잘못된 용량의 투약을 예방했다."
        },
        "expectedEvidence": [
          "용량 차이를 투약 보류가 필요한 문제로 판단한 구체적인 근거를 설명한다.",
          "처방의 안전성을 확신할 수 없었던 지점을 환자 위해 가능성과 연결한다."
        ]
      },
      "question": "푸른결종합병원에서 평소 두 배인 진통제 처방을 보고 투약을 멈추셨던데요. 단순한 용량 차이를 넘어 투약을 보류해야 한다고 판단한 근거는 무엇이었나요?",
      "answerTip": "당시 실제로 판단한 내용을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "투약을 보류한 근거를 해당 처방의 구체적인 상황에 연결해 설명한다.",
            "확인되지 않은 용량으로 투약했을 때의 환자 위해 가능성을 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소와 다른 용량이라 재확인이 필요했다고 답하지만 구체적인 위험 설명은 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 보류한 판단 근거를 설명하지 못하거나 처방은 무조건 수행해야 한다고 답한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "교대 시간대의 환자 위험을 다음 근무자에게 전달할 구체적인 인수인계 정보로 연결한 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동 사고 보고서에서 수술 후 첫 보행 환자의 낙상이 교대 시간대에 집중되었다.",
          "task": "다음 근무자가 환자의 보행 위험을 놓치지 않도록 인수인계 정보를 보완해야 했다.",
          "action": "진통제 투여 시각을 다음 근무자에게 전달해야 하는 이유를 판단해 항목 추가를 제안했다.",
          "result": "보완된 체크리스트로 위험 정보를 전달했고 분기 낙상 건수는 5건에서 2건으로 줄었다."
        },
        "expectedEvidence": [
          "진통제 투여 시각을 다음 근무자에게 반드시 전달해야 한다고 본 이유를 설명한다.",
          "투여 시각이 환자 상태 변화나 첫 보행 위험을 판단하는 데 주는 정보를 설명한다."
        ]
      },
      "question": "푸른결종합병원에서 교대 시간대 낙상에 대응해 인수인계에 진통제 투여 시각을 추가하셨던데요. 투여 시각을 다음 근무자에게 꼭 넘겨야 한다고 본 이유는 무엇이었나요?",
      "answerTip": "당시 상황을 떠올리며 핵심부터 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "진통제 투여 시각의 전달 필요성을 교대 시간대 첫 보행 환자의 위험과 연결해 설명한다.",
            "다음 근무자가 투여 시각으로 환자 상태나 보행 위험을 판단할 수 있는 이유를 구체화한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "다음 근무자의 환자 관찰에 필요했다고 답하지만 투여 시각이 필요한 이유는 일반적이다."
          ]
        },
        "poor": {
          "criteria": [
            "투여 시각을 전달해야 하는 이유를 설명하지 못하거나 낙상 감소 수치만 반복한다."
          ]
        }
      }
    }
  ]
}

